function fetch(ctx) {
  const seconds = Math.floor(ctx.now / 1000);
  const query = `appName=CailianpressWeb&last_time=${seconds}&os=web&refresh_type=1&rn=50&sv=7.7.5`;
  const sign = ctx.md5(ctx.sha1(query));
  const response = ctx.request({
    url: `https://www.cls.cn/v1/roll/get_roll_list?${query}&sign=${sign}`,
    headers: {Referer: 'https://www.cls.cn/telegraph'}
  });
  if (response.status !== 200) throw new Error(`上游 HTTP ${response.status}`);
  return ctx.mapJSON(response.text, {
  "itemsPath": "data.roll_data",
  "idPath": "id",
  "titlePath": "title",
  "bodyPaths": [
    "content",
    "brief"
  ],
  "datePath": "ctime",
  "dateUnit": "seconds",
  "urlTemplate": "https://www.cls.cn/detail/{id}",
  "exclude": [
    {
      "path": "is_ad",
      "op": "truthy"
    }
  ]
});
}

function fetch(ctx) {
  const response = ctx.request({
    url: 'https://api-one.wallstcn.com/apiv1/content/lives?channel=global-channel&limit=50'
  });
  if (response.status !== 200) throw new Error(`上游 HTTP ${response.status}`);
  return ctx.mapJSON(response.text, {
  "itemsPath": "data.items",
  "idPath": "id",
  "titlePath": "title",
  "bodyPaths": [
    "content_text",
    "content"
  ],
  "datePath": "display_time",
  "dateUnit": "seconds",
  "urlPath": "uri",
  "urlTemplate": "https://wallstreetcn.com/live/{id}"
});
}

function fetch(ctx) {
  const response = ctx.request({
    url: `https://www.jin10.com/flash_newest.js?t=${Math.floor(ctx.now / 1000)}`,
    headers: {Referer: 'https://www.jin10.com/'}
  });
  if (response.status !== 200) throw new Error(`上游 HTTP ${response.status}`);
  return ctx.mapJSON(response.text, {
  "itemsPath": "",
  "idPath": "id",
  "titlePath": "data.title",
  "bodyPaths": [
    "data.content"
  ],
  "datePath": "time",
  "dateUnit": "local",
  "timezone": "+08:00",
  "urlTemplate": "https://flash.jin10.com/detail/{id}",
  "jsonPrefix": "var newest =",
  "exclude": [
    {
      "path": "channel",
      "op": "contains",
      "value": 5
    },
    {
      "path": "data.lock",
      "op": "truthy"
    },
    {
      "path": "data.vip_level",
      "op": "gt",
      "value": 0
    }
  ]
});
}
